#include <string>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;
    std::regex regex(R"(# (\w+))");
    std::regex_replace(html, regex, "<h1>$1</h1>");
    std::regex_replace(html, regex, "<h2>$1</h2>");
    std::regex_replace(html, regex, "<h3>$1</h3>");
    std::regex_replace(html, regex, "<h4>$1</h4>");
    std::regex_replace(html, regex, "<h5>$1</h5>");
    std::regex_replace(html, regex, "<h6>$1</h6>");
    std::regex_replace(html, regex, "<h7>$1</h7>");
    std::regex_replace(html, regex, "<h8>$1</h8>");
    return html;
}
```

